<script setup>
import { ELEMENT, NODE } from './game.js';
import { useGame } from './useGame.js';
import GameIcon from './GameIcon.vue';
const g = useGame();
// Destructure refs so Vue templates unwrap them automatically.
const { phase, map, current, visited, team, hp, maxHp, attackBonus, board, enemy, turn, combos, totalDamage, busy, grabbed, pointerDrop, cursor, remaining, matched, choices, recruitCandidate, logs, helpOpen, restartOpen, clears, mobile, moveTime, available, augmented, edges } = g;
const point = n => ({ x: 60 + n.col * 110, y: 515 - n.row * 65 });
const isAvailable = n => phase.value === 'map' && available.value.some(a => a.id === n.id);
</script>

<template>
  <div class="app-shell">
    <header class="topbar">
      <a class="wordmark" href="#" @click.prevent="restartOpen = true"><span class="brand-icon"><GameIcon name="augment" :size="27" /></span> ROOTBOUND <span class="build-tag">ARCADE // 01</span></a>
      <nav><button class="quiet" @click="helpOpen = true">플레이 가이드 <span>↗</span></button><button class="quiet" :disabled="grabbed || busy" @click="restartOpen = true">새 탐험 ↻</button></nav>
    </header>
    <section class="page-heading"><div><div class="eyebrow"><span class="live-dot"></span> STAGE SELECT / THE WHISPERING WOODS</div><h1>속삭이는 숲</h1><p>한 번의 움직임, 수많은 가능성. 숲의 끝까지 당신만의 길을 만드세요.</p></div><div class="expedition"><span>탐험 진행</span><strong>{{ current ? current.row + 1 : 0 }}<small> / 8</small></strong><div class="segment-bar"><i v-for="i in 8" :key="i" :class="{ filled: current && i <= current.row + 1 }"></i></div></div></section>
    <main class="workspace">
      <aside class="map-panel panel"><div class="panel-heading"><div><span class="eyebrow">ROUTE SELECT</span><h2>탐험 지도</h2></div><span class="tiny-tag">STAGE MAP</span></div>
        <p class="map-caption">{{ phase === 'map' ? '빛나는 노드를 선택해 이동하세요.' : '현재 노드를 완료하면 길이 열립니다.' }}</p>
        <div class="route-map"><svg viewBox="0 0 340 565" role="img" aria-label="위쪽 보스로 향하는 8층 분기 경로"><defs><linearGradient id="pathFade" x1="0" y1="1" x2="0" y2="0"><stop stop-color="#a9c9a0"/><stop offset="1" stop-color="#597460"/></linearGradient></defs>
          <g v-for="edge in edges" :key="edge.from.id + edge.to.id"><line :x1="point(edge.from).x" :y1="point(edge.from).y" :x2="point(edge.to).x" :y2="point(edge.to).y" :class="['path-line', { traveled: visited.includes(edge.from.id) && visited.includes(edge.to.id) }]" /></g>
        </svg>
        <div v-for="row in map" :key="row[0].row" class="map-row" :style="{ bottom: (row[0].row * 65 + 26) / 565 * 100 + '%' }"><span class="floor-label">{{ row[0].row + 1 }}</span><button v-for="node in row" :key="node.id" class="map-node" :class="[node.type, { available: isAvailable(node), current: current?.id === node.id, visited: visited.includes(node.id) }]" :style="{ left: point(node).x / 340 * 100 + '%' }" :disabled="!isAvailable(node)" :aria-label="`${node.row + 1}층 ${node.col + 1}번 경로 ${NODE[node.type].name}`" :title="NODE[node.type].description" @click="g.selectNode(node)"><GameIcon :name="visited.includes(node.id) && current?.id !== node.id ? 'check' : node.type" :size="20" /></button></div>
        <div class="map-start">입구 <span>↑</span></div></div>
        <div class="map-legend"><span v-for="type in ['battle','elite','augment','rest','event','boss']" :key="type" :class="'legend-' + type"><GameIcon :name="type" :size="15" />{{ NODE[type].name }}</span></div>
      </aside>
      <section class="play-column">
        <section class="battle-panel panel">
          <div class="panel-heading"><div><span class="eyebrow">{{ current ? NODE[current.type].name : 'PRESS START' }}</span><h2>{{ phase === 'battle' ? '숲의 결투' : '다음 이야기를 향해' }}</h2></div><span class="tiny-tag">{{ phase === 'battle' ? `TURN ${turn.toString().padStart(2, '0')}` : 'EXPEDITION' }}</span></div>
          <template v-if="phase === 'battle'">
            <div class="enemy-scene" :class="enemy.element"><div class="scene-ring"></div><div class="enemy-sigil">{{ enemy.icon }}</div><div class="enemy-info"><span class="element-label" :style="{ color: ELEMENT[enemy.element].color }">{{ ELEMENT[enemy.element].icon }} {{ ELEMENT[enemy.element].name }} 속성</span><h3>{{ enemy.name }}</h3><div class="health-track enemy-health"><i :style="{ width: enemy.hp / enemy.maxHp * 100 + '%' }"></i></div><span class="health-numbers">{{ enemy.hp }} / {{ enemy.maxHp }}</span></div><div class="enemy-intent"><span>⚔ {{ enemy.counter }}턴 후</span><strong>{{ enemy.attack }} 피해</strong></div></div>
            <div class="combo-strip" aria-live="polite"><span><b>{{ combos }}</b> COMBO</span><span><b>{{ totalDamage }}</b> DAMAGE</span><span class="turn-state">{{ busy ? '연쇄 판정 중…' : grabbed ? '드롭을 놓으면 공격합니다' : '드롭을 잡아 움직이세요' }}</span></div>
            <div class="mobile-health"><span>♡ 파티 체력</span><div class="health-track party-health"><i :style="{ width: hp / maxHp * 100 + '%' }"></i></div><strong>{{ hp }} / {{ maxHp }}</strong></div>
            <div class="board-wrap"><div class="board" role="application" aria-label="6열 5행 퍼즐 보드. 방향키로 이동, 스페이스로 드롭 잡기와 놓기." tabindex="0" @pointerdown="g.pointerDown" @pointermove="g.pointerMove" @pointerup="g.pointerEnd" @pointercancel="g.pointerEnd" @lostpointercapture="g.pointerEnd" @keydown="g.keydown"><div v-for="(orb, i) in board" :key="i" class="cell" :data-cell="i" :class="{ active: cursor === i, held: cursor === i && grabbed, 'pointer-held': cursor === i && !!pointerDrop, matching: matched.includes(i) }"><span class="orb" :class="orb" :aria-label="ELEMENT[orb].name">{{ ELEMENT[orb].icon }}</span></div></div></div>
            <div class="timer-line"><span>◷ 조작 시간</span><div class="timer-track"><i :style="{ width: remaining / moveTime * 100 + '%' }"></i></div><strong>{{ remaining.toFixed(1) }}<small>s</small></strong></div>
            <p class="input-tip">{{ mobile ? '드롭을 터치한 채 움직이고 손을 떼면 공격합니다.' : '마우스 드래그 · 방향키 / WASD 이동 · Space 잡기 / 놓기' }}<br><span>첫 이동부터 시간이 흐릅니다. 같은 드롭 3개를 가로·세로로 연결하세요.</span></p>
          </template>
          <div v-else class="interlude">
            <template v-if="phase === 'map'"><div class="forest-art"><span><GameIcon name="augment" :size="76" /></span><i></i><i></i><i></i></div><span class="eyebrow">CHOOSE YOUR ROUTE</span><h3>{{ current ? '조금 더 깊은 곳으로' : '당신의 탐험이 시작됩니다' }}</h3><p>지도에서 다음 경로를 선택하세요.<br>전투와 휴식, 새로운 동료가 기다립니다.</p><div class="next-choices"><button v-for="node in available" :key="node.id" class="route-choice" @click="g.selectNode(node)"><span class="choice-icon" :class="node.type"><GameIcon :name="node.type" :size="27" /></span><strong>{{ NODE[node.type].name }}</strong><small>{{ NODE[node.type].description }}</small><b>선택 →</b></button></div></template>
            <template v-else-if="phase === 'augment'"><div class="interlude-symbol"><GameIcon name="augment" :size="46" /></div><span class="eyebrow">POWER UP</span><h3>어떤 힘을 깨울까요?</h3><p>하나를 선택하세요. 효과는 이번 탐험 동안 유지됩니다.</p><div class="reward-list"><button v-for="a in choices" :key="a.id" class="reward-card" @click="g.chooseAugment(a)"><span class="reward-icon"><GameIcon :name="a.id" :size="27" /></span><div><small>{{ a.rarity }} 증강</small><h4>{{ a.name }}</h4><p>{{ a.desc }}</p></div><span>↗</span></button></div></template>
            <template v-else-if="phase === 'reward'"><div class="interlude-symbol"><GameIcon name="check" :size="46" /></div><span class="eyebrow">STAGE CLEAR</span><h3>승리가 남긴 선물</h3><p>동료를 영입하거나 지금의 파티를 강화하세요. 하나만 선택할 수 있습니다.</p><div class="reward-list"><button class="reward-card" @click="g.chooseGrowth('monster')"><span class="reward-icon">{{ recruitCandidate.icon }}</span><div><small>동료 영입 · {{ ELEMENT[recruitCandidate.element].name }} · ATK {{ recruitCandidate.attack }}</small><h4>{{ recruitCandidate.name }}</h4><p>{{ team.length >= 6 ? '파티원 한 명을 교체합니다.' : '파티에 새 몬스터가 합류합니다.' }}</p></div><span>＋</span></button><button class="reward-card" @click="g.chooseGrowth('train')"><span class="reward-icon"><GameIcon name="power" :size="27" /></span><div><small>파티 강화</small><h4>함께 성장하기</h4><p>전체 공격력 +6 · 최대 체력 및 현재 체력 +20</p></div><span>＋</span></button><button class="reward-card" @click="g.chooseGrowth('heal')"><span class="reward-icon"><GameIcon name="heal" :size="27" /></span><div><small>회복</small><h4>따뜻한 보급품</h4><p>체력을 95 회복합니다.</p></div><span>＋</span></button></div></template>
            <template v-else-if="phase === 'replace'"><div class="interlude-symbol"><GameIcon name="monster" :size="46" /></div><h3>새로운 동료의 자리</h3><p>{{ recruitCandidate.name }}과 교체할 파티원을 선택하세요.</p><div class="replacement-list"><button v-for="(m,i) in team" :key="i" class="reward-card" @click="g.replaceMonster(i)">{{ m.icon }} {{ m.name }} · ATK {{ m.attack + attackBonus }} <span>교체 →</span></button></div><button class="text-button" @click="g.replaceMonster(-1)">영입 대신 파티 강화 선택</button></template>
            <template v-else-if="phase === 'rest'"><div class="interlude-symbol"><GameIcon name="rest" :size="46" /></div><span class="eyebrow">REST STOP</span><h3>잠시, 숨을 고르세요</h3><p>나뭇잎 사이로 따뜻한 빛이 내려앉습니다.</p><div class="reward-list"><button class="reward-card" @click="g.rest(false)"><span class="reward-icon"><GameIcon name="heal" :size="27" /></span><div><h4>모닥불 곁에서 쉬기</h4><p>최대 체력의 45%를 회복합니다.</p></div></button><button class="reward-card" @click="g.rest(true)"><span class="reward-icon"><GameIcon name="power" :size="27" /></span><div><h4>함께 수련하기</h4><p>전체 공격력을 8 올립니다.</p></div></button></div></template>
            <template v-else-if="phase === 'event'"><div class="interlude-symbol"><GameIcon name="event" :size="46" /></div><span class="eyebrow">BONUS EVENT</span><h3>잊힌 제단의 속삭임</h3><p>작은 대가를 바치면 오래된 힘이 깨어납니다.</p><div class="reward-list"><button class="reward-card" :disabled="hp <= Math.round(maxHp * .2)" @click="g.eventChoice(true)"><span class="reward-icon"><GameIcon name="augment" :size="27" /></span><div><h4>생명력 바치기</h4><p>체력 {{ Math.round(maxHp * .2) }} 소모 → 증강 선택</p></div></button><button class="reward-card" @click="g.eventChoice(false)"><span class="reward-icon"><GameIcon name="heal" :size="27" /></span><div><h4>샘물을 마시고 떠나기</h4><p>체력을 25 회복합니다.</p></div></button></div></template>
            <template v-else-if="phase === 'won' || phase === 'lost'"><div class="interlude-symbol"><GameIcon :name="phase === 'won' ? 'boss' : 'event'" :size="46" /></div><span class="eyebrow">{{ phase === 'won' ? 'GAME CLEAR' : 'UNTIL THE NEXT JOURNEY' }}</span><h3>{{ phase === 'won' ? '숲은 당신을 기억합니다' : '탐험은 여기까지' }}</h3><p>{{ clears }}번의 승리 · {{ augmented.reduce((s,a) => s + a.count, 0) }}개의 증강 · {{ team.length }}명의 동료<br>새로운 경로와 선택으로 다시 도전하세요.</p><button class="primary" @click="g.reset">새로운 탐험 시작 ↗</button></template>
          </div>
        </section>
        <section class="party-panel panel"><div class="panel-heading"><h2>함께하는 동료 <span class="muted">{{ team.length }}/6</span></h2><span class="eyebrow">{{ phase === 'battle' ? '클릭하면 스킬 사용' : 'YOUR PARTY' }}</span></div><div class="party-grid"><button v-for="(m,i) in team" :key="i" class="monster-card" :style="{ '--element': ELEMENT[m.element].color }" :disabled="phase !== 'battle' || busy || grabbed || m.cooldown > 0" @click="g.skill(i)" :title="`${m.name}: ${m.skill}`"><span class="monster-element">{{ ELEMENT[m.element].icon }}</span><span class="monster-art">{{ m.icon }}</span><strong>{{ m.name }}</strong><span class="monster-atk">ATK {{ m.attack + attackBonus }}</span><span class="skill-label">{{ phase !== 'battle' ? ELEMENT[m.element].name + ' 속성' : m.cooldown ? m.cooldown + '턴 대기' : '스킬 사용' }}</span></button><div v-for="i in 6-team.length" :key="'empty'+i" class="empty-slot"><span>＋</span><small>새로운 동료</small></div></div></section>
      </section>
      <aside class="status-column"><section class="panel vitality-panel"><div class="panel-heading"><h2>탐험 상태</h2><span class="live-dot"></span></div><div class="hp-label"><span>♡ 파티 체력</span><strong>{{ hp }} <small>/ {{ maxHp }}</small></strong></div><div class="health-track party-health"><i :style="{ width: hp / maxHp * 100 + '%' }"></i></div><div class="stat-row"><span>기본 공격력 합계</span><strong>{{ team.reduce((s,m) => s + m.attack + attackBonus, 0) }}</strong></div><div class="stat-row"><span>드롭 조작 시간</span><strong>{{ moveTime.toFixed(1) }}s</strong></div><div class="stat-row"><span>클리어한 전투</span><strong>{{ clears }}</strong></div></section>
        <section class="panel augments-panel"><div class="panel-heading"><h2>획득한 증강</h2><span class="tiny-tag">{{ augmented.reduce((s,a) => s+a.count, 0) }}</span></div><div v-if="!augmented.length" class="empty-augments"><span>✧</span><p>아직 깨어나지 않은 힘</p><small>제단과 정예 전투에서<br>새로운 증강을 발견하세요.</small></div><div v-for="a in augmented" :key="a.id" class="augment-row"><span class="augment-icon"><GameIcon :name="a.id" :size="20" /></span><div><strong>{{ a.name }} <small v-if="a.count > 1">×{{ a.count }}</small></strong><p>{{ a.desc }}</p></div></div></section>
        <section class="panel journal-panel"><div class="panel-heading"><h2>탐험 기록</h2><span class="eyebrow">RUN LOG</span></div><ol><li v-for="(line,i) in logs.slice(0,5)" :key="i">{{ line }}</li></ol></section>
        <p class="footnote">모든 성장은 이번 탐험에만 적용됩니다.<br>새로고침하면 새로운 회차가 시작됩니다.</p>
      </aside>
    </main>
    <Teleport to="body"><span v-if="pointerDrop" class="orb dragged-orb" :class="pointerDrop.element" :style="{ left: pointerDrop.x + 'px', top: pointerDrop.y + 'px', width: pointerDrop.size + 'px', height: pointerDrop.size + 'px' }" aria-hidden="true">{{ ELEMENT[pointerDrop.element].icon }}</span></Teleport>
    <footer><span>✳ ROOTBOUND</span><span>퍼즐로 연결하는 나만의 탐험</span><span>Vue · JavaScript</span></footer>
    <div v-if="helpOpen || restartOpen" class="modal-backdrop" @click.self="helpOpen = restartOpen = false"><section class="modal panel" role="dialog" aria-modal="true" :aria-label="helpOpen ? '플레이 가이드' : '새 탐험'" @keydown.esc="helpOpen = restartOpen = false"><button class="close-modal" @click="helpOpen = restartOpen = false" aria-label="닫기">×</button><template v-if="helpOpen"><span class="eyebrow">HOW TO PLAY</span><h2>한 번의 드래그로, 더 많은 콤보를.</h2><p>6×5 보드에서 드롭 하나를 잡고 움직이면 지나간 드롭과 자리가 바뀝니다. 첫 이동부터 6초가 흐르며, 놓거나 시간이 끝나면 가로·세로 3개 이상의 매치가 동시에 터집니다. 떨어진 드롭의 추가 매치도 콤보에 포함됩니다.</p><p>{{ mobile ? '터치: 드롭을 누른 채 움직이고 손을 떼세요.' : '마우스: 드래그 후 놓기. 키보드: 보드를 클릭하거나 Tab으로 초점을 맞춘 뒤 방향키/WASD로 커서를 이동하세요. Space/Enter로 잡고, 방향키로 옮긴 뒤 Space/Enter로 놓습니다.' }}</p><p>해당 속성 몬스터가 파티에 있어야 공격합니다. ♥ 드롭은 체력을 회복합니다. 불 → 숲 → 물 → 불, 빛 ↔ 어둠 상성은 피해 2배입니다. 불·숲·물의 역상성은 피해 0.5배입니다.</p><p>전투 중 동료 카드를 누르면 같은 속성 드롭 5개를 만듭니다. 정예 전투는 성장 보상과 증강을 모두 주며, 8층 보스를 쓰러뜨리면 승리합니다.</p><button class="primary" @click="helpOpen = false">탐험으로 돌아가기</button></template><template v-else><h2>새롭게 시작할까요?</h2><p>현재 탐험의 파티와 증강이 초기화됩니다.</p><div class="modal-actions"><button class="quiet" @click="restartOpen = false">계속 탐험</button><button class="primary" @click="g.reset">새 탐험 시작</button></div></template></section></div>
  </div>
</template>
